1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Damage = {
12	  itemType: string;
13	  amount: number;
14	};
15	
16	export type Incident = {
17	  cause: string;
18	  damages: readonly Damage[];
19	};
20	
21	export type QuoteStep = {
22	  op: "quote";
23	  items: readonly Item[];
24	};
25	
26	export type ClaimStep = {
27	  op: "claim";
28	  // Zero-based index of the quote step that created the policy.
29	  policy: number;
30	  incident: Incident;
31	};
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: readonly Step[];
38	};
39	
40	export type QuoteResult = { premium: number };
41	export type ClaimResult = { payout: number; remainingCap: number };
42	
43	// One entry per scenario step, in order. Each step's `op` selects the shape.
44	export type StepResult = QuoteResult | ClaimResult;
45	
46	export type ScenarioResult = {
47	  results: StepResult[];
48	};
49	
50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	// Every percentage modifier is a delta computed against an *unmodified* base
64	// and summed with the others — modifiers never compound. Policy-wide ones use
65	// the policy base, item-specific ones the affected item's own base premium.
66	//
67	// Percentages stay in integer percent points: multiply first, divide by 100
68	// last. A float multiplier such as `base * 1.1` yields 110.00000000000001 for
69	// a sword and breaks the ceil. `(base * 10) / 100` gives exactly 10.
70	const percentOf = (amount: number, percent: number): number =>
71	  (amount * percent) / 100;
72	
73	const BLOCK_SIZE = 3;
74	const BLOCK_BASE_PREMIUM = 60;
75	
76	const countByType = (items: readonly Item[]): Map<string, number> => {
77	  const counts = new Map<string, number>();
78	
79	  for (const item of items) {
80	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
81	  }
82	
83	  return counts;
84	};
85	
86	const baseOfGroup = (type: string, count: number): number =>
87	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
88	
89	const policyBaseOf = (items: readonly Item[]): number =>
90	  [...countByType(items)].reduce(
91	    (total, [type, count]) => total + baseOfGroup(type, count),
92	    0,
93	  );
94	
95	// A modifier rule: when `applies` holds for the subject, `percent` percent of
96	// the relevant base premium is added. A negative percent is a discount. Every
97	// rule whose predicate holds contributes; the deltas are summed, never
98	// compounded.
99	type ModifierRule<Subject> = {
100	  applies: (subject: Subject) => boolean;
101	  percent: number;
102	};
103	
104	const sumApplicablePercents = <Subject>(
105	  rules: ModifierRule<Subject>[],
106	  subject: Subject,
107	): number =>
108	  rules.reduce(
109	    (total, rule) => (rule.applies(subject) ? total + rule.percent : total),
110	    0,
111	  );
112	
113	// Policy-wide modifiers: each is a percentage of the policy base premium.
114	//
115	// Their subject is the *policy* — the circumstances under which this quote is
116	// issued — not the customer alone. Today those circumstances are just who is
117	// asking; rules that also depend on where the quote sits in the scenario read
118	// the field they need off the same subject.
119	type Policy = {
120	  customer: Customer;
121	  // Zero-based ordinal among the customer's quotes in this scenario.
122	  quoteOrdinal: number;
123	};
124	
125	const LOYALTY_YEARS_THRESHOLD = 2;
126	const LOYALTY_DISCOUNT_PERCENT = -20;
127	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = -15;
128	
129	const POLICY_MODIFIER_RULES: ModifierRule<Policy>[] = [
130	  { applies: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
131	  {
132	    applies: ({ customer }) =>
133	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
134	    percent: LOYALTY_DISCOUNT_PERCENT,
135	  },
136	  {
137	    applies: ({ quoteOrdinal }) => quoteOrdinal > 0,
138	    percent: FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
139	  },
140	];
141	
142	const policyModifierDelta = (policyBase: number, policy: Policy): number =>
143	  percentOf(policyBase, sumApplicablePercents(POLICY_MODIFIER_RULES, policy));
144	
145	// Item-specific modifiers: each is a percentage of the affected item's own
146	// base premium.
147	const CURSE_SURCHARGE_PERCENT = 50;
148	const HIGH_ENCHANTMENT_THRESHOLD = 5;
149	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
150	
151	const ITEM_MODIFIER_RULES: ModifierRule<Item>[] = [
152	  { applies: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
153	  {
154	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
155	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
156	  },
157	];
158	
159	const itemModifierDelta = (item: Item): number =>
160	  percentOf(
161	    BASE_PREMIUMS[item.type],
162	    sumApplicablePercents(ITEM_MODIFIER_RULES, item),
163	  );
164	
165	const quote = (items: readonly Item[], policy: Policy): number => {
166	  const policyBase = policyBaseOf(items);
167	  const modifiers =
168	    policyModifierDelta(policyBase, policy) +
169	    items.reduce((total, item) => total + itemModifierDelta(item), 0);
170	
171	  // Rounding is in the MHPCO's favour: premiums round up.
172	  return Math.ceil(policyBase + modifiers) + PROCESSING_FEE;
173	};
174	
175	// Insurance values are what an item is insured FOR, distinct from the base
176	// premium charged to insure it.
177	const INSURANCE_VALUES: Record<string, number> = {
178	  sword: 1000,
179	  amulet: 600,
180	  staff: 800,
181	  potion: 400,
182	  rune: 250,
183	  moonstone: 250,
184	};
185	
186	const DEDUCTIBLE_PER_DAMAGE = 100;
187	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
188	
189	const insuranceSumOf = (items: readonly Item[]): number =>
190	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
191	
192	// A policy as a claim sees it: the items it covers, and how much of its cap
193	// is still available. Successive claims against the same policy draw the cap
194	// down, so `remainingCap` is state that outlives the claim step that reads it.
195	type IssuedPolicy = {
196	  items: readonly Item[];
197	  remainingCap: number;
198	};
199	
200	const issuePolicy = (items: readonly Item[]): IssuedPolicy => ({
201	  items,
202	  remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items),
203	});
204	
205	// A reimbursement clause: when `applies` holds for the damaged item, the
206	// damage is reimbursed at `percent` of its amount.
207	//
208	// Unlike the premium modifiers above, clauses do NOT sum. When several apply
209	// the most restrictive one wins — the lowest percentage. So a clause table
210	// needs no ordering to be correct, and adding a clause can only ever lower a
211	// payout, never raise it.
212	type ReimbursementClause = {
213	  applies: (item: Item) => boolean;
214	  percent: number;
215	};
216	
217	const FULL_REIMBURSEMENT_PERCENT = 100;
218	const HALVED_REIMBURSEMENT_ENCHANTMENT = 8;
219	const HALVED_REIMBURSEMENT_PERCENT = 50;
220	
221	const REIMBURSEMENT_CLAUSES: ReimbursementClause[] = [
222	  {
223	    applies: (item) =>
224	      (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT,
225	    percent: HALVED_REIMBURSEMENT_PERCENT,
226	  },
227	];
228	
229	// Full reimbursement is the default: with no clause applying, the damage is
230	// covered in full.
231	const reimbursementPercentFor = (item: Item): number =>
232	  REIMBURSEMENT_CLAUSES.reduce(
233	    (percent, clause) =>
234	      clause.applies(item) ? Math.min(percent, clause.percent) : percent,
235	    FULL_REIMBURSEMENT_PERCENT,
236	  );
237	
238	// What a single damage entry settles for, before the policy's cap is applied:
239	// the reimbursement its clauses allow, less the deductible. The deductible is
240	// charged once per damaged item, not once per incident, so it belongs here
241	// rather than at the incident level.
242	//
243	// Takes the whole policy rather than the damage alone because the clauses
244	// grade the reimbursement by the *damaged item's* properties (enchantment,
245	// material), which only the policy can resolve from itemType.
246	// The damaged item is matched by type alone, so with two swords insured both
247	// sword damages resolve to the first. That is harmless while every item of a
248	// type is interchangeable for reimbursement purposes; the case that forces a
249	// positional match is rejecting more damage entries of a type than the policy
250	// covers, which needs a count rather than a lookup.
251	const settlementForDamage = (policy: IssuedPolicy, damage: Damage): number => {
252	  const damagedItem = policy.items.find(
253	    (item) => item.type === damage.itemType,
254	  );
255	
256	  const reimbursement = damagedItem
257	    ? percentOf(damage.amount, reimbursementPercentFor(damagedItem))
258	    : damage.amount;
259	
260	  return reimbursement - DEDUCTIBLE_PER_DAMAGE;
261	};
262	
263	// Settles one incident against a policy, returning the payout and the policy
264	// as it stands afterwards. The cap is drawn down here — that is what makes a
265	// second claim against the same policy see less headroom than the first.
266	const settleClaim = (
267	  policy: IssuedPolicy,
268	  incident: Incident,
269	): { payout: number; policy: IssuedPolicy } => {
270	  const settlement = incident.damages.reduce(
271	    (total, damage) => total + settlementForDamage(policy, damage),
272	    0,
273	  );
274	
275	  // Rounding is in the MHPCO's favour: payouts round down, mirroring the
276	  // premium's round up.
277	  // The policy pays at most what is left of its cap.
278	  const payout = Math.min(Math.floor(settlement), policy.remainingCap);
279	
280	  return {
281	    payout,
282	    policy: { ...policy, remainingCap: policy.remainingCap - payout },
283	  };
284	};
285	
286	// What the scenario has established by the time a step runs. Threaded through
287	// the steps in order: each step reads it, and hands the next step the progress
288	// its own execution made.
289	type ScenarioProgress = {
290	  // How many quotes the customer has already been given. Only quote steps
291	  // advance this, so an op that is not a quote leaves it untouched.
292	  quotesSoFar: number;
293	  // Policies created by earlier quote steps, keyed by their step index — the
294	  // handle a later claim step names in its `policy` field.
295	  policies: Map<number, IssuedPolicy>;
296	};
297	
298	// Runs one step against the progress so far, returning its result alongside
299	// the progress the *next* step inherits. Dispatch on `step.op` lives here:
300	// a new op is a new branch, and the loop below is unaffected.
301	const runStep = (
302	  step: Step,
303	  stepIndex: number,
304	  customer: Customer,
305	  progress: ScenarioProgress,
306	): { result: StepResult; progress: ScenarioProgress } => {
307	  if (step.op === "claim") {
308	    const settled = settleClaim(
309	      progress.policies.get(step.policy) ?? issuePolicy([]),
310	      step.incident,
311	    );
312	
313	    return {
314	      result: {
315	        payout: settled.payout,
316	        remainingCap: settled.policy.remainingCap,
317	      },
318	      // The drawn-down policy replaces the one the claim was made against, so
319	      // the next claim against it starts from the reduced cap.
320	      progress: {
321	        ...progress,
322	        policies: new Map(progress.policies).set(step.policy, settled.policy),
323	      },
324	    };
325	  }
326	
327	  return {
328	    result: {
329	      premium: quote(step.items, {
330	        customer,
331	        quoteOrdinal: progress.quotesSoFar,
332	      }),
333	    },
334	    progress: {
335	      quotesSoFar: progress.quotesSoFar + 1,
336	      policies: new Map(progress.policies).set(
337	        stepIndex,
338	        issuePolicy(step.items),
339	      ),
340	    },
341	  };
342	};
343	
344	export const runScenario = (scenario: Scenario): ScenarioResult => {
345	  const results: StepResult[] = [];
346	  let progress: ScenarioProgress = { quotesSoFar: 0, policies: new Map() };
347	
348	  for (const [stepIndex, step] of scenario.steps.entries()) {
349	    const stepRun = runStep(step, stepIndex, scenario.customer, progress);
350	
351	    results.push(stepRun.result);
352	    progress = stepRun.progress;
353	  }
354	
355	  return { results };
356	};
